// ---------------------------------------------------------------------------
// Topological sort
// ---------------------------------------------------------------------------

function topologicalSort(repos) {
    var normalised = repos.map(function(r) {
        return typeof r === 'string' ? { name: r } : r;
    });
    var byName = {};
    normalised.forEach(function(r) { byName[r.name] = r; });

    var sorted = [];
    var visited = {};

    function visit(name) {
        if (visited[name]) return;
        visited[name] = true;
        var r = byName[name];
        if (r && Array.isArray(r.depends_on)) {
            r.depends_on.forEach(function(dep) { if (byName[dep]) visit(dep); });
        }
        if (r) sorted.push(r);
    }

    normalised.forEach(function(r) { visit(r.name); });
    return sorted;
}

// ---------------------------------------------------------------------------
// Shared section builders (pure) — used by the Jira/ADO/Confluence formatters
// ---------------------------------------------------------------------------

/** 'a, b' for non-empty depends_on, em-dash otherwise. */
function formatRepoDeps(r) {
    return (Array.isArray(r.depends_on) && r.depends_on.length > 0)
        ? r.depends_on.join(', ')
        : '\u2014';
}

/** GFM/wiki table rows: | # | name | reason | deps | */
function buildRepoTableRows(sorted) {
    var rows = [];
    sorted.forEach(function(r, idx) {
        rows.push('| ' + (idx + 1) + ' | ' + r.name + ' | ' + (r.reason || '') + ' | ' + formatRepoDeps(r) + ' |');
    });
    return rows;
}

/** Mermaid dependency edges ('    dep --> name'), in sorted order. */
function buildDependencyEdges(sorted) {
    var edges = [];
    sorted.forEach(function(r) {
        if (Array.isArray(r.depends_on)) {
            r.depends_on.forEach(function(dep) { edges.push('    ' + dep + ' --> ' + r.name); });
        }
    });
    return edges;
}

function buildJiraSection(sorted) {
    var lines = [];
    lines.push('----');
    lines.push('h2. Affected Repositories');
    lines.push('');
    lines.push('|| # || Repository || Reason || Depends On ||');

    buildRepoTableRows(sorted).forEach(function(row) { lines.push(row); });

    // Mermaid diagram (only when there are edges)
    var edges = buildDependencyEdges(sorted);
    if (edges.length > 0) {
        lines.push('');
        lines.push('{code}');
        lines.push('graph LR');
        edges.forEach(function(e) { lines.push(e); });
        lines.push('{code}');
    }

    // JSON anchor for createRepoTasks script
    lines.push('');
    lines.push('{code:json|title=affected_repos}');
    lines.push(JSON.stringify(sorted, null, 2));
    lines.push('{code}');
    lines.push('----');

    return lines.join('\n');
}

// ---------------------------------------------------------------------------
// Formatter — ADO / Markdown
// ---------------------------------------------------------------------------

function buildMarkdownSection(sorted) {
    var lines = [];
    lines.push('---');
    lines.push('## Affected Repositories');
    lines.push('');
    lines.push('| # | Repository | Reason | Depends On |');
    lines.push('|---|---|---|---|');

    buildRepoTableRows(sorted).forEach(function(row) { lines.push(row); });

    var edges = buildDependencyEdges(sorted);
    if (edges.length > 0) {
        lines.push('');
        lines.push('```mermaid');
        lines.push('graph LR');
        edges.forEach(function(e) { lines.push(e); });
        lines.push('```');
    }

    lines.push('');
    lines.push('```json');
    lines.push(JSON.stringify(sorted, null, 2));
    lines.push('```');
    lines.push('---');

    return lines.join('\n');
}

// ---------------------------------------------------------------------------
// Formatter — Confluence markdown (no JSON anchor; that's tracker-field-only)
// ---------------------------------------------------------------------------

function buildConfluenceMarkdownSection(sorted) {
    var lines = [];
    lines.push('## Affected Repositories');
    lines.push('');
    lines.push('| # | Repository | Reason | Depends On |');
    lines.push('|---|---|---|---|');

    buildRepoTableRows(sorted).forEach(function(row) { lines.push(row); });

